package practice;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Supplier;

/**
 * Builds report exporters from configuration: each key ("pdf", "csv", ...) names the class that
 * exports that format. The registry is built once, when the reporting service starts.
 */
public class ExporterRegistry {

    /** What every configured class must implement. */
    public interface Exporter {
        String export(String report);
    }

    /** A configuration entry the registry can't use. */
    public static class ConfigException extends RuntimeException {
        public ConfigException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    private final ClassLoader loader;
    private final Map<String, Supplier<Exporter>> exporters = new LinkedHashMap<>();

    /** {@code config} maps each key to the binary name of a class, as read from the config file. */
    public ExporterRegistry(Map<String, String> config, ClassLoader loader) {
        this.loader = loader;
        config.forEach((key, className) -> exporters.put(key, resolve(key, className)));
    }

    /** A new exporter for {@code key}. */
    public Exporter create(String key) {
        Supplier<Exporter> exporter = exporters.get(key);
        if (exporter == null) {
            throw new ConfigException("no exporter configured for '" + key + "'", null);
        }
        return exporter.get();
    }

    /** Creates an instance with the class's no-argument constructor. */
    static Exporter newInstance(Class<? extends Exporter> type) {
        try {
            return type.getDeclaredConstructor().newInstance();
        } catch (ReflectiveOperationException e) {
            throw new ConfigException("cannot create " + type.getName(), e);
        }
    }

    Supplier<Exporter> resolve(String key, String className) {
        Class<? extends Exporter> type;
        try {
            type = Class.forName(className, false, loader).asSubclass(Exporter.class);
        } catch (ClassNotFoundException | ClassCastException e) {
            throw new ConfigException("exporter '" + key + "': " + className + " is not an Exporter class", e);
        }
        return () -> newInstance(type);
    }
}

package practice;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ClassLoader loader = TryIt.class.getClassLoader();
            Map<String, String> config = new LinkedHashMap<>();
            config.put("csv", "practice.TryIt$CsvExporter");
            config.put("audit", "practice.TryIt$AuditExporter");
            ExporterRegistry registry = new ExporterRegistry(config, loader);
            System.out.println("setup run while building: " + SETUP);
            System.out.println("csv: " + registry.create("csv").export("June sales"));
            System.out.println("audit: " + registry.create("audit").export("June sales"));
            System.out.println("setup run after first use: " + SETUP);
            try {
                new ExporterRegistry(Map.of("pdf", "practice.TryIt$PdfExportr"), loader);
            } catch (ExporterRegistry.ConfigException bad) {
                System.out.println("misspelt entry: " + bad.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    static final List<String> SETUP = new ArrayList<>();
    public static class CsvExporter implements ExporterRegistry.Exporter {
        public String export(String report) { return report.replace(' ', ';'); }
    }
    public static class AuditExporter implements ExporterRegistry.Exporter {
        static { SETUP.add("audit template loaded"); }
        public String export(String report) { return "[audited] " + report; }
    }
}

